def fetch_prev_year(term_num):

    current_date = datetime.date.today()
    active_year = float(current_date.year)
    active_month = int(current_date.month)
    if active_month >= 5:
        active_year += 0.6
    # For term num between 1 to 8, year always takes values between 12 to 15
    earlier_year = int(math.floor(active_year - (term_num + 1)/float(2)))
    earlier_year -= 2000
    return str(earlier_year)

