def build_interpreter(base_type, interpreter_type_title):

        mod_title, type_title = interpreter_type_title.rsplit('.', 1)
        mod_instance = importlib.import_module(mod_title)
        target_type = getattr(mod_instance, type_title)
        if not issubclass(target_type, base_type):
            raise TypeError(
                "Class {type_title!r} of module {mod_title!r} doesn't "
                "implement 'NetworkLayoutInterpreter' interface.".format(
                    type_title=type_title, mod_title=mod_title))
        return target_type()

def run_time_constraint(self, target_result, default=3600.0 * 24 * 365 * 10):

    optimal = self.results_query(objective_ordered=True).first()
    if optimal is None:
      if target_result.limit:
        return target_result.limit
      else:
        return default

    if target_result.limit:
      return min(target_result.limit, self.upper_bound_multiplier * optimal.time)
    else:
      return self.default_bound_multiplier * optimal.time

