        if vertex == self.boundary.orientation_neg:
            return self.linesegment_negative
        elif vertex == self.boundary.orientation_pos:
            return self.linesegment_positive
        else:
            raise AttributeError("Specified vertex is not one of the terminal boundary vertices")

def timestamp_to_synergy(time_label, date_obj):

    if time_label == QUALIFIER_HOURLY:
        date_pattern = SYNERGY_HOURLY_PATTERN
    elif time_label == QUALIFIER_DAILY:
        date_pattern = SYNERGY_DAILY_PATTERN
    elif time_label == QUALIFIER_MONTHLY:
        date_pattern = SYNERGY_MONTHLY_PATTERN
    elif time_label == QUALIFIER_YEARLY:
        date_pattern = SYNERGY_YEARLY_PATTERN
    elif time_label == QUALIFIER_REAL_TIME:
        date_pattern = SYNERGY_SESSION_PATTERN
    else:
        raise ValueError('unknown time qualifier: {0}'.format(time_label))
    return date_obj.strftime(date_pattern)

def meeting_to_epoch(datetimemark):

    utc_timeparts = datetime.strptime(datetimemark, SYNERGY_MEETING_PATTERN).replace(tzinfo=None).utctimetuple()
    return calendar.timegm(utc_timeparts)
